public class SessionCredentialsTest {

    @Test
    public void testEquals() {
        // Create first SessionCredentials instance
        SessionCredentials sessionCredential1 = new SessionCredentials("RocketMQ", "12345678");
        sessionCredential1.setSecurityToken("abcd");

        // Create second SessionCredentials instance
        SessionCredentials sessionCredential2 = new SessionCredentials("RocketMQ", "12345678", "abcd");

        // Update content for both instances
        Properties props1 = new Properties();
        props1.setProperty(SessionCredentials.ACCESS_KEY, sessionCredential1.getAccessKey());
        props1.setProperty(SessionCredentials.SECRET_KEY, sessionCredential1.getSecretKey());
        props1.setProperty(SessionCredentials.SECURITY_TOKEN, sessionCredential1.getSecurityToken());
        sessionCredential1.updateContent(props1);

        Properties props2 = new Properties();
        props2.setProperty(SessionCredentials.ACCESS_KEY, sessionCredential2.getAccessKey());
        props2.setProperty(SessionCredentials.SECRET_KEY, sessionCredential2.getSecretKey());
        props2.setProperty(SessionCredentials.SECURITY_TOKEN, sessionCredential2.getSecurityToken());
        sessionCredential2.updateContent(props2);

        // First check: should be equal
        Assert.assertTrue(sessionCredential1.equals(sessionCredential2));

        // Modify sessionCredential2's secretKey and signature
        sessionCredential2.setSecretKey("87654321");
        sessionCredential2.setSignature("newSignature");

        // Second check: should not be equal
        Assert.assertFalse(sessionCredential1.equals(sessionCredential2));
    }
}

